/* GAME SCRIPT START */
const canvas=document.querySelector('#view'),ctx=canvas.getContext('2d'),mapCanvas=document.querySelector('#map'),mctx=mapCanvas.getContext('2d');
let W=640,H=360,started=false,paused=true,last=0,elapsed=0,toastTimer=0,modal='',gameOver=false;
const grid=[
'####################','##......##.........#','##......##.........#','##......##..###....#','##......D..##......#','##......##..##.....#','##......##..##.....#','##......##..##.....#','##......##..##.....#','##......##..##.....#','##................#','##..####...####...##','##..#..#...#..#...##','##..#..D...D..#...##','##..#..#...#..#...##','##..####...####...##','##................#','##.....##.........##','##.....##.........##','####################'];
const GW=20,GH=20,doors=[{x:8.5,y:4.5,open:false,boards:0},{x:7.5,y:13.5,open:false,boards:0},{x:12.5,y:13.5,open:false,boards:0}];
const player={x:4.4,y:10.4,a:0,health:100,stamina:100,hunger:100,weapon:'Pipe wrench',bullets:6,attack:0,hurt:0};
const inventory={Scrap:3,Wood:2,Cloth:1,Food:2,Gas:1,Parts:0,Boards:0,Ammo:6,Medkit:1};
const props=[
 {type:'cache',name:'Corner market',x:3.6,y:3.7,used:false,loot:{Food:2,Cloth:1}},
 {type:'cache',name:'Tool locker',x:5.7,y:6.5,used:false,loot:{Scrap:3,Parts:2}},
 {type:'cache',name:'First aid kit',x:14.5,y:2.7,used:false,loot:{Medkit:1,Cloth:1}},
 {type:'cache',name:'Abandoned duffel',x:16.5,y:8.4,used:false,loot:{Ammo:4,Food:1}},
 {type:'cache',name:'Hardware store',x:4.2,y:14.7,used:false,loot:{Wood:4,Scrap:2}},
 {type:'car',name:'Rusty sedan',x:15.5,y:15.8,hp:0,gas:0},
 {type:'cache',name:'Cabinet',x:10.3,y:7.7,used:false,loot:{Wood:2,Food:1}}
];
const zombies=[{x:6.8,y:4.5,hp:60,speed:.42},{x:13.9,y:5.8,hp:60,speed:.34},{x:16.8,y:10.3,hp:60,speed:.38},{x:5.2,y:16.8,hp:60,speed:.3},{x:13.5,y:17,hp:60,speed:.37},{x:10.1,y:3.3,hp:60,speed:.32}];
const keys={},touch={};let mouseDown=false,looking=false,toastTimeout;
function resize(){const dpr=Math.min(1.5,devicePixelRatio||1);W=canvas.clientWidth;H=canvas.clientHeight;canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);mapCanvas.width=132;mapCanvas.height=132;}
addEventListener('resize',resize);resize();
function say(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>el.classList.remove('show'),2100)}
function wall(x,y){const gx=Math.floor(x),gy=Math.floor(y);if(gx<0||gy<0||gx>=GW||gy>=GH)return true;const c=grid[gy][gx];if(c==='#')return true;if(c==='D'){const d=doors.find(d=>Math.floor(d.x)===gx&&Math.floor(d.y)===gy);return !d?.open}return false}
function solid(x,y){if(wall(x,y))return true;return doors.some(d=>!d.open&&d.boards>0&&Math.floor(d.x)===Math.floor(x)&&Math.floor(d.y)===Math.floor(y))}
function move(dx,dy){if(!solid(player.x+dx*2,player.y))player.x+=dx*2;if(!solid(player.x,player.y+dy*2))player.y+=dy*2}
function normalize(a){while(a>Math.PI)a-=Math.PI*2;while(a< -Math.PI)a+=Math.PI*2;return a}
function raycast(){const fov=Math.PI/3,depth=new Float32Array(W+1);ctx.fillStyle='#84928a';ctx.fillRect(0,0,W,H*.44);let sky=ctx.createLinearGradient(0,0,0,H*.48);sky.addColorStop(0,'#67736c');sky.addColorStop(.68,'#b3a78a');sky.addColorStop(1,'#737564');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H*.52);let floor=ctx.createLinearGradient(0,H*.43,0,H);floor.addColorStop(0,'#55584a');floor.addColorStop(.28,'#363a30');floor.addColorStop(1,'#171c17');ctx.fillStyle=floor;ctx.fillRect(0,H*.45,W,H*.55);
 const rays=Math.min(560,Math.ceil(W)),step=W/rays;for(let i=0;i<rays;i++){const screen=i*step,ang=player.a+(i/rays-.5)*fov,rx=Math.cos(ang),ry=Math.sin(ang);let dist=.02,hit='';while(dist<22){const xx=player.x+rx*dist,yy=player.y+ry*dist;if(wall(xx,yy)){hit=grid[Math.floor(yy)]?.[Math.floor(xx)]||'#';break}dist+=.025}const corrected=dist*Math.cos(ang-player.a);depth[Math.floor(screen)]=corrected;const wh=Math.min(H*1.6,H/(corrected*.84)),top=H*.49-wh/2;let side=(Math.abs((player.x+rx*dist)%1)<.07||Math.abs((player.y+ry*dist)%1)<.07),shade=Math.max(34,176-corrected*10-(side?22:0));let color=hit==='D'?'#6c4a34':`rgb(${shade*.86|0},${shade*.91|0},${shade*.79|0})`;ctx.fillStyle=color;ctx.fillRect(screen,top,step+1,wh);ctx.fillStyle='rgba(20,18,14,.32)';for(let yy=top+8;yy<top+wh;yy+=22)ctx.fillRect(screen,yy,step+1,1);if(hit==='D'){ctx.fillStyle='#a2774e';ctx.fillRect(screen,top+wh*.18,step+1,2)}ctx.fillStyle=`rgba(13,17,14,${Math.min(.66,corrected*.04)})`;ctx.fillRect(screen,top,step+1,wh)}
 // horizon haze and distant building silhouettes
 ctx.fillStyle='rgba(49,58,50,.32)';for(let i=0;i<8;i++){let x=(i*117+elapsed*2)%W;ctx.fillRect(x,H*.36,34,H*.13)}
 return {depth,fov,step};}
function project(x,y,fov){const dx=x-player.x,dy=y-player.y,dist=Math.hypot(dx,dy),angle=normalize(Math.atan2(dy,dx)-player.a);if(Math.abs(angle)>fov*.72||dist<.12)return null;return {x:W/2+Math.tan(angle)/(Math.tan(fov/2))*W/2,y:H*.49,dist,scale:H/(dist*.92),angle}}
function drawObject(o,depth,fov,step){const p=project(o.x,o.y,fov);if(!p)return;const sx=p.x,scale=p.scale;if(p.dist>21)return;const size=Math.min(H*1.4,scale),base=H*.51;ctx.save();ctx.translate(sx,base);
 if(o.type==='zombie'){
  const w=size*.38,h=size*.92;ctx.globalAlpha=Math.min(1,Math.max(.35,1-p.dist/22));ctx.fillStyle='rgba(0,0,0,.25)';ctx.beginPath();ctx.ellipse(0,0,w*.7,h*.09,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#353b30';ctx.fillRect(-w*.38,-h*.55,w*.76,h*.46);ctx.fillStyle='#727d66';ctx.beginPath();ctx.arc(0,-h*.67,w*.28,0,Math.PI*2);ctx.fill();ctx.fillStyle='#aa684e';ctx.fillRect(-w*.24,-h*.69,w*.11,h*.04);ctx.fillRect(w*.08,-h*.69,w*.11,h*.04);ctx.strokeStyle='#656e59';ctx.lineWidth=Math.max(2,w*.13);ctx.beginPath();ctx.moveTo(-w*.31,-h*.5);ctx.lineTo(-w*.55,-h*.17);ctx.moveTo(w*.31,-h*.5);ctx.lineTo(w*.5,-h*.22);ctx.stroke();ctx.fillStyle='#161a15';ctx.fillRect(-w*.4,-h*.08,w*.31,h*.1);ctx.fillRect(w*.08,-h*.08,w*.31,h*.1);if(o.hp<60){ctx.fillStyle='#9e5945';ctx.fillRect(-w*.3,-h*.86,w*.6*o.hp/60,Math.max(2,scale*.025))}
 }else if(o.type==='car'){const w=size*.94,h=size*.42;ctx.fillStyle='#181b17';ctx.fillRect(-w/2,-h,w,h);ctx.fillStyle=o.hp>0?'#69736a':'#704e3b';ctx.fillRect(-w*.44,-h*.9,w*.88,h*.65);ctx.fillStyle='#252f2e';ctx.fillRect(-w*.27,-h*.83,w*.54,h*.3);ctx.fillStyle='#a6a177';ctx.fillRect(-w*.48,-h*.18,w*.16,h*.1);ctx.fillRect(w*.32,-h*.18,w*.16,h*.1);ctx.fillStyle='#0a0c0a';ctx.fillRect(-w*.38,-h*.04,w*.25,h*.14);ctx.fillRect(w*.14,-h*.04,w*.25,h*.14);}
 else {const w=size*.42,h=size*.45;ctx.fillStyle=o.used?'#554b3b':'#9a8058';ctx.fillRect(-w/2,-h,w,h);ctx.fillStyle='#3d4132';ctx.fillRect(-w*.38,-h*.83,w*.76,h*.32);ctx.fillStyle='#bba574';ctx.fillRect(-w*.12,-h*.72,w*.24,h*.09);}
 ctx.restore();}

