function nearest(){let best=null,bestD=1.65;for(const o of props){const d=Math.hypot(o.x-player.x,o.y-player.y);if(d<bestD){best=o;bestD=d}}for(const d of doors){const dist=Math.hypot(d.x+.0-player.x,d.y+.0-player.y);if(dist<bestD){best=d;bestD=dist}}return best?{obj:best,dist:bestD}:null}
function render(){if(!W||!H)return;ctx.clearRect(0,0,W,H);const {depth,fov,step}=raycast();const things=[...props.filter(p=>!p.used||p.type==='car'),...zombies.filter(z=>z.hp>0).map(z=>({...z,type:'zombie'}))].sort((a,b)=>Math.hypot(b.x-player.x,b.y-player.y)-Math.hypot(a.x-player.x,a.y-player.y));for(const o of things){const p=project(o.x,o.y,fov);if(!p)continue;const ix=Math.min(W-1,Math.max(0,Math.floor(p.x)));if(depth[ix]&&p.dist>depth[ix]+.18)continue;drawObject(o,depth,fov,step)}
 // weapon silhouette
 const swing=player.attack>0?Math.sin((.32-player.attack)/.32*Math.PI)*42:0;ctx.save();ctx.translate(W*.73,H*.9+swing);ctx.rotate(-.16);ctx.fillStyle='#302920';ctx.fillRect(-6,-H*.22,22,H*.29);ctx.fillStyle=player.weapon==='9mm pistol'?'#252823':'#80674a';ctx.fillRect(-H*.04,-H*.3,H*.08,H*.31);ctx.fillStyle='#b49b69';ctx.fillRect(-H*.12,-H*.33,H*.24,H*.07);ctx.restore();if(player.hurt>0){ctx.fillStyle=`rgba(150,25,20,${player.hurt*.38})`;ctx.fillRect(0,0,W,H)}
 drawMap();let near=nearest(),prompt=document.querySelector('#prompt');if(near&&!modal&&!gameOver){const o=near.obj;let text;if(o.type==='car')text=o.hp>0?`<kbd>E</kbd> DRIVE · <kbd>R</kbd> REPAIR ENGINE`:`<kbd>E</kbd> INSPECT · <kbd>R</kbd> REPAIR`;else if(o.type==='cache')text=o.used?'EMPTY':`<kbd>E</kbd> SEARCH ${o.name.toUpperCase()}`;else text=o.open?`<kbd>E</kbd> CLOSE DOOR · <kbd>B</kbd> BOARD UP`:`<kbd>E</kbd> OPEN DOOR · <kbd>B</kbd> BOARD UP`;prompt.innerHTML=text;prompt.style.display='block'}else prompt.style.display='none';}
function drawMap(){const s=132/GW;mctx.fillStyle='#141a14';mctx.fillRect(0,0,132,132);for(let y=0;y<GH;y++)for(let x=0;x<GW;x++){let c=grid[y][x];mctx.fillStyle=c==='#'?'#45483d':c==='D'?'#af714c':'#242c23';mctx.fillRect(x*s,y*s,s-.7,s-.7)}for(const o of props){mctx.fillStyle=o.type==='car'?'#c08857':o.used?'#77745e':'#d0bd7d';mctx.fillRect(o.x*s-2,o.y*s-2,4,4)}for(const z of zombies)if(z.hp>0){mctx.fillStyle='#b34f40';mctx.fillRect(z.x*s-2,z.y*s-2,4,4)}mctx.fillStyle='#d5dfa9';mctx.beginPath();mctx.arc(player.x*s,player.y*s,3.3,0,Math.PI*2);mctx.fill();mctx.strokeStyle='#d5dfa9';mctx.beginPath();mctx.moveTo(player.x*s,player.y*s);mctx.lineTo((player.x+Math.cos(player.a)*1.3)*s,(player.y+Math.sin(player.a)*1.3)*s);mctx.stroke()}
