function interact(){const n=nearest();if(!n){say('Nothing close enough to interact with.');return}const o=n.obj;if(o.type==='cache'){if(o.used){say('Nothing left in there.');return}Object.entries(o.loot).forEach(([k,v])=>item(k,v));o.used=true;say(`Searched ${o.name}. Supplies recovered.`);updateHUD()}else if(o.type==='car'){openModal('car')}else if(o.open){o.open=false;say('Door closed.')}else{o.open=true;say('Door opened. Stay sharp.') }}
function boardDoor(){const n=nearest();if(!n||!('boards'in n.obj)){say('Get closer to a door or window first.');return}const d=n.obj;if(d.open){say('Close the door before boarding it.');return}if(!take('Boards',2)){say('Need 2 wooden boards. Craft some with [C].');return}d.boards=Math.min(3,d.boards+1);say(`Barricade reinforced · ${d.boards}/3 boards.`)}
function repairCar(){const c=props.find(x=>x.type==='car');if(c.hp){say('Engine is already repaired.');return}if(!take('Repair kit',1)){say('Craft a repair kit first: 2 parts + 2 scrap.');return}c.hp=100;say('Engine repaired.');openModal('car')}
function fuelCar(){const c=props.find(x=>x.type==='car');if(!take('Gas',1)){say('No gas can. Search the county.');return}c.gas=100;say('Fuel added.');openModal('car')}
function attack(){if(!started||modal||gameOver)return;if(player.weapon==='9mm pistol'){if((inventory.Ammo||0)<=0){say('Click. Empty. Craft rounds at [C].');return}take('Ammo',1);player.attack=.16;let target=null,score=99;for(const z of zombies){if(z.hp<=0)continue;const d=Math.hypot(z.x-player.x,z.y-player.y),a=Math.abs(normalize(Math.atan2(z.y-player.y,z.x-player.x)-player.a));if(d<9&&a<.18&&d<score){target=z;score=d}}if(target){target.hp-=52;say(target.hp<=0?'One less of them.':'Hit. Keep moving.')}else say('Shot fired. The street heard you.');zombies.forEach(z=>{if(Math.hypot(z.x-player.x,z.y-player.y)<9)z.alert=8});return}
 if(player.stamina<9){say('Too exhausted to swing.');return}player.stamina-=9;player.attack=.32;let target=null,score=2.25;for(const z of zombies){if(z.hp<=0)continue;const d=Math.hypot(z.x-player.x,z.y-player.y),a=Math.abs(normalize(Math.atan2(z.y-player.y,z.x-player.x)-player.a));if(d<score&&a<.82){target=z;score=d}}if(target){target.hp-=player.weapon==='Makeshift spear'?42:32;say(target.hp<=0?'Zombie down.':'You landed a hit.')}else say('The wrench cuts through empty air.')}
function consume(){if(inventory.Food>0&&player.hunger<95){take('Food');player.hunger=Math.min(100,player.hunger+34);say('You eat something. It tastes like dust.')}else if(inventory.Medkit>0&&player.health<100){take('Medkit');player.health=Math.min(100,player.health+45);say('Medkit used.')}else say('Nothing useful to use right now.');updateHUD()}
function setWeapon(which){if(which===1){player.weapon='Pipe wrench'}else if(which===2){player.weapon='9mm pistol'}else return;updateHUD()}
function startGame(){document.querySelector('#title').style.display='none';started=true;paused=false;last=performance.now();if(innerWidth>700&&canvas.requestPointerLock)canvas.requestPointerLock();say('Find shelter before dark. Search every building.')}
document.querySelector('#start').onclick=startGame;document.querySelector('#restart').onclick=()=>location.reload();document.querySelector('#close').onclick=()=>closeModal();document.querySelector('#touchInteract').onclick=interact;document.querySelector('#touchAttack').onpointerdown=e=>{e.preventDefault();attack()};document.querySelector('#touchCraft').onclick=()=>openModal('craft');
for(const b of document.querySelectorAll('[data-move]')){const k=b.dataset.move;b.onpointerdown=e=>{e.preventDefault();touch[k]=true};for(const ev of ['pointerup','pointercancel','pointerleave'])b.addEventListener(ev,()=>touch[k]=false)}
addEventListener('keydown',e=>{const k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();keys[k]=true;if(k==='escape'){if(modal)closeModal();else if(document.pointerLockElement)document.exitPointerLock();}if(!started)return;if(k==='e')interact();if(k==='b')boardDoor();if(k==='f')interact();if(k==='c')openModal('craft');if(k==='i')openModal('inventory');if(k==='1')setWeapon(1);if(k==='2')setWeapon(2);if(k==='h'||k==='m')consume();if(k===' '&&!e.repeat)attack()});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
canvas.addEventListener('click',()=>{if(started&&!modal&&innerWidth>700&&!document.pointerLockElement)canvas.requestPointerLock();if(started&&!modal&&innerWidth>700)attack()});addEventListener('mousemove',e=>{if(started&&!modal&&document.pointerLockElement){player.a+=e.movementX*.0022;player.a=normalize(player.a)}});let touchX=0;canvas.addEventListener('touchstart',e=>{if(innerWidth<=700){touchX=e.touches[0].clientX}},{passive:true});canvas.addEventListener('touchmove',e=>{if(innerWidth<=700&&started&&!modal){const x=e.touches[0].clientX;player.a=normalize(player.a+(x-touchX)*.009);touchX=x}},{passive:true});
function tick(now){requestAnimationFrame(tick);const dt=Math.min(.05,(now-last)/1000||0);last=now;if(started&&!paused&&!gameOver){elapsed+=dt;player.attack=Math.max(0,player.attack-dt);player.hurt=Math.max(0,player.hurt-dt);player.hunger=Math.max(0,player.hunger-dt*.04);if(player.hunger<=0&&Math.random()<dt*.12)player.health-=1;
 let mx=0,my=0,forward=(keys.w||keys.arrowup||touch.forward?1:0)-(keys.s||keys.arrowdown||touch.back?1:0),side=(keys.d||keys.arrowright||touch.right?1:0)-(keys.a||keys.arrowleft||touch.left?1:0);if(forward||side){const sprint=keys.shift&&player.stamina>2,speed=(sprint?2.45:1.55)*dt;if(sprint)player.stamina=Math.max(0,player.stamina-dt*17);else player.stamina=Math.min(100,player.stamina+dt*9);const norm=Math.hypot(forward,side)||1;mx=(Math.cos(player.a)*forward+Math.cos(player.a+Math.PI/2)*side)/norm*speed;my=(Math.sin(player.a)*forward+Math.sin(player.a+Math.PI/2)*side)/norm*speed;move(mx,my)}else player.stamina=Math.min(100,player.stamina+dt*13);
 for(const z of zombies){if(z.hp<=0)continue;const d=Math.hypot(player.x-z.x,player.y-z.y);z.alert=Math.max(0,(z.alert||0)-dt);if(d<8||z.alert>0){const vx=(player.x-z.x)/(d||1),vy=(player.y-z.y)/(d||1),sp=(z.speed+(elapsed>100?.07:0))*dt;if(d>0.63){if(!solid(z.x+vx*sp,z.y))z.x+=vx*sp;if(!solid(z.x,z.y+vy*sp))z.y+=vy*sp}else if(Math.random()<dt*.85){player.health-=7;player.hurt=.5;say('A zombie caught you!');}}}
 if(player.health<=0){player.health=0;gameOver=true;paused=true;document.querySelector('#death').style.display='flex';document.querySelector('#deathDay').textContent='01';document.querySelector('#deathMsg').textContent=`You survived ${Math.floor(elapsed/60)} minutes in Dead County.`}
 updateHUD()}render();}
requestAnimationFrame(tick);
/* GAME SCRIPT END */
</script></body></html>

