 <style>
 :root{--ink:#e7e5d7;--muted:#a9aa98;--rust:#cb7246;--lime:#c0d092;--panel:rgba(16,21,17,.94);--line:rgba(214,221,193,.17)}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#101510;color:var(--ink);font-family:Inter,ui-sans-serif,system-ui,-apple-system,Segoe UI,sans-serif}button{font:inherit;color:inherit;cursor:pointer}#game{position:relative;width:100vw;height:100dvh;background:#171d16;overflow:hidden}canvas#view{position:absolute;inset:0;width:100%;height:100%;image-rendering:pixelated}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at center,transparent 45%,rgba(0,0,0,.62) 100%),linear-gradient(0deg,rgba(0,0,0,.42),transparent 25%,transparent 75%,rgba(0,0,0,.12)}
